import { useEffect, useState } from 'react';
import { useNavigate, useParams } from 'react-router-dom';
import Box from '@mui/material/Box';
import Button from '@mui/material/Button';
import Checkbox from '@mui/material/Checkbox';
import FormControlLabel from '@mui/material/FormControlLabel';
import FormHelperText from '@mui/material/FormHelperText';
import Stack from '@mui/material/Stack';
import TextField from '@mui/material/TextField';
import Typography from '@mui/material/Typography';
import { Booking, CheckoutValues, loadBooking, saveBooking } from '../../booking';
import { createReservation } from '../../api';
import { getBookingItems, totalPrice } from '../../seatUtils';
import { useToast } from '../../toast/ToastProvider';
import { validate, FieldErrors } from './checkoutValidation';

type TouchedState = Record<keyof FieldErrors, boolean>;

const INITIAL_TOUCHED: TouchedState = {
  firstName: false,
  lastName: false,
  email: false,
  confirmEmail: false,
  phone: false,
  terms: false,
};

export function CheckoutPage() {
  const { screeningId } = useParams();
  const navigate = useNavigate();
  const showToast = useToast();

  const [booking, setBooking] = useState<Booking | null>(null);
  const [guardFailed, setGuardFailed] = useState(false);
  const [touched, setTouched] = useState<TouchedState>(INITIAL_TOUCHED);
  const [submitting, setSubmitting] = useState(false);

  useEffect(() => {
    const existing = loadBooking();
    if (
      !existing ||
      existing.paid ||
      existing.screeningId !== Number(screeningId) ||
      existing.seats.length === 0
    ) {
      setGuardFailed(true);
      navigate('/', { replace: true });
      return;
    }
    setBooking(existing);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [screeningId]);

  if (guardFailed || !booking) {
    return null;
  }

  const values = booking.checkout;
  const errors = validate(values);
  const total = totalPrice(booking.seats);

  function updateValues(partial: Partial<CheckoutValues>) {
    if (!booking) return;
    const updated = { ...booking, checkout: { ...booking.checkout, ...partial } };
    setBooking(updated);
    saveBooking(updated);
  }

  function markTouched(field: keyof TouchedState) {
    setTouched((prev) => ({ ...prev, [field]: true }));
  }

  function handleBack() {
    navigate(`/screenings/${screeningId}/summary`);
  }

  async function handlePay() {
    if (!booking) return;
    const currentErrors = validate(booking.checkout);
    if (Object.keys(currentErrors).length > 0) {
      setTouched({
        firstName: true,
        lastName: true,
        email: true,
        confirmEmail: true,
        phone: true,
        terms: true,
      });
      showToast('The form contains errors');
      return;
    }

    setSubmitting(true);
    try {
      const items = getBookingItems(booking.seats);
      const seats = items.flatMap((item) => item.ids);
      await createReservation({
        screeningId: Number(screeningId),
        seats,
        customer: {
          firstName: booking.checkout.firstName,
          lastName: booking.checkout.lastName,
          email: booking.checkout.email,
          phone: booking.checkout.phone,
        },
        totalPrice: total,
      });
      const updated = { ...booking, paid: true, customerEmail: booking.checkout.email };
      saveBooking(updated);
      navigate('/confirmation');
    } catch {
      setSubmitting(false);
      showToast('Payment failed. Please try again.');
    }
  }

  const showError = (field: keyof FieldErrors) => touched[field] && Boolean(errors[field]);

  return (
    <Box maxWidth={520} mx="auto" p={3}>
      <Typography variant="h4" data-testid="checkout-title" gutterBottom>
        Your details
      </Typography>

      <Stack spacing={2}>
        <TextField
          label="First name *"
          value={values.firstName}
          onChange={(e) => updateValues({ firstName: e.target.value })}
          onBlur={() => markTouched('firstName')}
          error={showError('firstName')}
          helperText={showError('firstName') ? errors.firstName : undefined}
          slotProps={{
            htmlInput: { 'data-testid': 'first-name-input' },
            inputLabel: { 'data-testid': 'first-name-label' },
            formHelperText: { 'data-testid': 'first-name-error' },
          }}
        />

        <TextField
          label="Last name *"
          value={values.lastName}
          onChange={(e) => updateValues({ lastName: e.target.value })}
          onBlur={() => markTouched('lastName')}
          error={showError('lastName')}
          helperText={showError('lastName') ? errors.lastName : undefined}
          slotProps={{
            htmlInput: { 'data-testid': 'last-name-input' },
            inputLabel: { 'data-testid': 'last-name-label' },
            formHelperText: { 'data-testid': 'last-name-error' },
          }}
        />

        <TextField
          label="Email *"
          value={values.email}
          onChange={(e) => updateValues({ email: e.target.value })}
          onBlur={() => markTouched('email')}
          error={showError('email')}
          helperText={showError('email') ? errors.email : undefined}
          slotProps={{
            htmlInput: { 'data-testid': 'email-input' },
            inputLabel: { 'data-testid': 'email-label' },
            formHelperText: { 'data-testid': 'email-error' },
          }}
        />

        <TextField
          label="Confirm email *"
          value={values.confirmEmail}
          onChange={(e) => updateValues({ confirmEmail: e.target.value })}
          onBlur={() => markTouched('confirmEmail')}
          error={showError('confirmEmail')}
          helperText={showError('confirmEmail') ? errors.confirmEmail : undefined}
          slotProps={{
            htmlInput: { 'data-testid': 'confirm-email-input' },
            inputLabel: { 'data-testid': 'confirm-email-label' },
            formHelperText: { 'data-testid': 'confirm-email-error' },
          }}
        />

        <TextField
          label="Phone number"
          value={values.phone}
          onChange={(e) => updateValues({ phone: e.target.value })}
          onBlur={() => markTouched('phone')}
          error={showError('phone')}
          helperText={showError('phone') ? errors.phone : undefined}
          slotProps={{
            htmlInput: { 'data-testid': 'phone-input' },
            inputLabel: { 'data-testid': 'phone-label' },
            formHelperText: { 'data-testid': 'phone-error' },
          }}
        />

        <Box>
          <FormControlLabel
            control={
              <Checkbox
                data-testid="terms-checkbox"
                checked={values.acceptTerms}
                onChange={(e) => {
                  updateValues({ acceptTerms: e.target.checked });
                  markTouched('terms');
                }}
              />
            }
            label={<span data-testid="terms-label">I accept the terms and conditions *</span>}
          />
          {showError('terms') && (
            <FormHelperText error data-testid="terms-error">
              {errors.terms}
            </FormHelperText>
          )}
        </Box>
      </Stack>

      <Stack direction="row" spacing={2} mt={3}>
        <Button data-testid="checkout-back-button" variant="outlined" onClick={handleBack}>
          Back
        </Button>
        <Button
          data-testid="pay-button"
          variant="contained"
          disabled={submitting}
          onClick={handlePay}
        >
          {submitting ? 'Processing…' : `Pay ${total.toFixed(2)} PLN`}
        </Button>
      </Stack>
    </Box>
  );
}

