interface TextFieldRowProps {
  id: string;
  label: string;
  labelTestId: string;
  inputTestId: string;
  errorTestId: string;
  value: string;
  onChange: (e: ChangeEvent<HTMLInputElement>) => void;
  onBlur: (e: FocusEvent<HTMLInputElement>) => void;
  showError: boolean;
  errorMessage?: string;
}

function TextFieldRow({
  id,
  label,
  labelTestId,
  inputTestId,
  errorTestId,
  value,
  onChange,
  onBlur,
  showError,
  errorMessage,
}: TextFieldRowProps) {
  return (
    <Box>
      <Typography component="label" htmlFor={id} data-testid={labelTestId} sx={{ display: 'block', mb: 0.5 }}>
        {label}
      </Typography>
      <TextField
        id={id}
        fullWidth
        value={value}
        onChange={onChange}
        onBlur={onBlur}
        error={showError}
        slotProps={{ htmlInput: { 'data-testid': inputTestId } }}
      />
      {showError && (
        <FormHelperText error data-testid={errorTestId}>
          {errorMessage}
        </FormHelperText>
      )}
    </Box>
  );
}

