import { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import Box from '@mui/material/Box';
import Button from '@mui/material/Button';
import Typography from '@mui/material/Typography';
import { Booking, clearBooking, loadBooking } from '../../booking';

export function ConfirmationPage() {
  const navigate = useNavigate();
  const [booking, setBooking] = useState<Booking | null>(null);
  const [guardFailed, setGuardFailed] = useState(false);

  useEffect(() => {
    const existing = loadBooking();
    if (!existing || !existing.paid) {
      setGuardFailed(true);
      navigate('/', { replace: true });
      return;
    }
    setBooking(existing);
  }, [navigate]);

  if (guardFailed || !booking) {
    return null;
  }

  function handleContinue() {
    clearBooking();
    navigate('/');
  }

  return (
    <Box sx={{ maxWidth: 520, mx: 'auto', p: 3, textAlign: 'center' }}>
      <Typography variant="h4" data-testid="confirmation-heading" gutterBottom>
        Payment successful
      </Typography>
      <Typography data-testid="confirmation-message" gutterBottom>
        Your tickets will be sent shortly to {booking.customerEmail}
      </Typography>
      <Button data-testid="confirmation-continue-button" variant="contained" onClick={handleContinue}>
        Continue
      </Button>
    </Box>
  );
}

import { useEffect, useState } from 'react';
import { useNavigate, useParams } from 'react-router-dom';
import Box from '@mui/material/Box';
import Button from '@mui/material/Button';
import List from '@mui/material/List';
import ListItem from '@mui/material/ListItem';
import Stack from '@mui/material/Stack';
import Typography from '@mui/material/Typography';
import { fetchMovie, fetchScreening } from '../../api';
import type { Movie, Screening } from '../../types';
import { Booking, loadBooking, saveBooking } from '../../booking';
import { formatPrice, getBookingItems, seatDescription, totalPrice } from '../../seatUtils';

export function SummaryPage() {
  const { screeningId } = useParams();
  const navigate = useNavigate();

  const [booking, setBooking] = useState<Booking | null>(null);
  const [screening, setScreening] = useState<Screening | null>(null);
  const [movie, setMovie] = useState<Movie | null>(null);
  const [guardFailed, setGuardFailed] = useState(false);

  useEffect(() => {
    const existing = loadBooking();
    if (
      !existing ||
      existing.paid ||
      existing.screeningId !== Number(screeningId) ||
      existing.seats.length === 0
    ) {
      setGuardFailed(true);
      navigate('/', { replace: true });
      return;
    }
    setBooking(existing);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [screeningId]);

  useEffect(() => {
    if (guardFailed) return;
    let cancelled = false;
    async function load() {
      try {
        const loadedScreening = await fetchScreening(screeningId as string);
        if (cancelled) return;
        setScreening(loadedScreening);
        const loadedMovie = await fetchMovie(loadedScreening.movieId);
        if (cancelled) return;
        setMovie(loadedMovie);
      } catch {
        if (!cancelled) {
          navigate('/', { replace: true });
        }
      }
    }
    load();
    return () => {
      cancelled = true;
    };
  }, [screeningId, guardFailed, navigate]);

  if (guardFailed || !booking || !screening || !movie) {
    return null;
  }

  const items = getBookingItems(booking.seats);

  function handleRemove(ids: string[]) {
    if (!booking) return;
    const newSeats = booking.seats.filter((id) => !ids.includes(id));
    const updated = { ...booking, seats: newSeats };
    saveBooking(updated);
    if (newSeats.length === 0) {
      navigate(`/screenings/${screeningId}/seats`);
      return;
    }
    setBooking(updated);
  }

  function handleBack() {
    navigate(`/screenings/${screeningId}/seats`);
  }

  function handleConfirm() {
    navigate(`/screenings/${screeningId}/checkout`);
  }

  return (
    <Box sx={{ maxWidth: 720, mx: 'auto', p: 3 }}>
      <Typography variant="h4" data-testid="summary-title" gutterBottom>
        Your tickets
      </Typography>

      <List data-testid="summary-list">
        {items.map((item) => (
          <ListItem
            key={item.ids.join('+')}
            data-testid="summary-item"
            sx={{ display: 'flex', justifyContent: 'space-between', gap: 2 }}
          >
            <Stack>
              <Typography data-testid="summary-item-title">{movie.title}</Typography>
              <Typography data-testid="summary-item-datetime">
                {screening.date} {screening.time}
              </Typography>
              <Typography data-testid="summary-item-row">{item.row}</Typography>
              <Typography data-testid="summary-item-seat">{seatDescription(item)}</Typography>
              <Typography data-testid="summary-item-price">{formatPrice(item.price)}</Typography>
            </Stack>
            <Button
              data-testid="summary-item-remove-button"
              variant="outlined"
              onClick={() => handleRemove(item.ids)}
            >
              Remove
            </Button>
          </ListItem>
        ))}
      </List>

      <Typography data-testid="summary-total" variant="h6">
        Total: {totalPrice(booking.seats).toFixed(2)} PLN
      </Typography>

      <Stack direction="row" spacing={2} sx={{ mt: 2 }}>
        <Button data-testid="back-button" variant="outlined" onClick={handleBack}>
          Back
        </Button>
        <Button data-testid="confirm-button" variant="contained" onClick={handleConfirm}>
          Confirm
        </Button>
      </Stack>
    </Box>
  );
}

import Box from '@mui/material/Box';
import Stack from '@mui/material/Stack';
import Typography from '@mui/material/Typography';
import { SeatState } from '../../seatUtils';

const LEGEND_ITEMS: { state: SeatState; label: string; color: string }[] = [
  { state: 'available', label: 'Available', color: '#2E7D32' },
  { state: 'selected', label: 'Selected', color: '#F9A825' },
  { state: 'unavailable', label: 'Unavailable', color: '#C62828' },
  { state: 'accessible', label: 'Accessible', color: '#1565C0' },
];

export function Legend() {
  return (
    <Stack data-testid="legend" direction="row" spacing={3} sx={{ justifyContent: 'center' }}>
      {LEGEND_ITEMS.map(({ state, label, color }) => (
        <Stack
          key={state}
          data-testid="legend-item"
          data-state={state}
          direction="row"
          spacing={1}
          sx={{ alignItems: 'center' }}
        >
          <Box sx={{ width: 16, height: 16, borderRadius: '4px', bgcolor: color }} />
          <Typography variant="body2">{label}</Typography>
        </Stack>
      ))}
    </Stack>
  );
}

import { useEffect, useMemo, useState } from 'react';
import { useNavigate, useParams } from 'react-router-dom';
import Box from '@mui/material/Box';
import Button from '@mui/material/Button';
import Stack from '@mui/material/Stack';
import Typography from '@mui/material/Typography';
import { fetchMovie, fetchScreening } from '../../api';
import type { Movie, Screening } from '../../types';
import { Booking, emptyBooking, loadBooking, saveBooking, clearBooking } from '../../booking';
import { formatShowDate } from '../../dateUtils';
import { MAX_SEATS, seatId } from '../../seatUtils';
import { useToast } from '../../toast/ToastProvider';
import { AuditoriumMap, ScreenIndicator } from './AuditoriumMap';
import { Legend } from './Legend';
import { SelectedSeatsPanel } from './SelectedSeatsPanel';

export function SeatSelectionPage() {
  const { screeningId } = useParams();
  const navigate = useNavigate();
  const showToast = useToast();

  const [screening, setScreening] = useState<Screening | null>(null);
  const [movie, setMovie] = useState<Movie | null>(null);
  const [booking, setBooking] = useState<Booking | null>(null);

  useEffect(() => {
    let cancelled = false;
    async function load() {
      try {
        const loadedScreening = await fetchScreening(screeningId as string);
        if (cancelled) return;
        setScreening(loadedScreening);
        const loadedMovie = await fetchMovie(loadedScreening.movieId);
        if (cancelled) return;
        setMovie(loadedMovie);
      } catch {
        if (!cancelled) {
          navigate('/', { replace: true });
        }
      }
    }
    load();
    return () => {
      cancelled = true;
    };
  }, [screeningId, navigate]);

  useEffect(() => {
    if (!screening) return;
    const existing = loadBooking();
    if (existing && !existing.paid && existing.screeningId === screening.id) {
      setBooking(existing);
    } else {
      const fresh = emptyBooking(screening.id);
      saveBooking(fresh);
      setBooking(fresh);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [screening?.id]);

  const occupiedSeats = useMemo(() => new Set(screening?.occupiedSeats ?? []), [screening]);
  const selectedSeats = useMemo(() => new Set(booking?.seats ?? []), [booking]);

  function updateSeats(newSeats: string[]) {
    if (!booking) return;
    const updated = { ...booking, seats: newSeats };
    setBooking(updated);
    saveBooking(updated);
  }

  function handleToggleSeat(row: number, column: number) {
    if (!booking) return;
    const id = seatId(row, column);
    if (selectedSeats.has(id)) {
      updateSeats(booking.seats.filter((s) => s !== id));
      return;
    }
    if (booking.seats.length + 1 > MAX_SEATS) {
      showToast('Maximum 10 seats per booking');
      return;
    }
    updateSeats([...booking.seats, id]);
  }

  function handleToggleCouch(row: number, columnStart: number, columnEnd: number) {
    if (!booking) return;
    const idA = seatId(row, columnStart);
    const idB = seatId(row, columnEnd);
    if (selectedSeats.has(idA) && selectedSeats.has(idB)) {
      updateSeats(booking.seats.filter((s) => s !== idA && s !== idB));
      return;
    }
    if (booking.seats.length + 2 > MAX_SEATS) {
      showToast('Maximum 10 seats per booking');
      return;
    }
    updateSeats([...booking.seats, idA, idB]);
  }

  function handleCancel() {
    clearBooking();
    navigate('/');
  }

  function handleContinue() {
    if (!booking || booking.seats.length === 0) return;
    navigate(`/screenings/${screeningId}/summary`);
  }

  if (!screening || !movie || !booking) {
    return null;
  }

  return (
    <Box sx={{ maxWidth: 1200, mx: 'auto', p: 3 }}>
      <Stack spacing={2} sx={{ alignItems: 'center' }}>
        <Typography variant="h4" data-testid="seat-map-title" sx={{ alignSelf: 'flex-start' }}>
          Choose your seats
        </Typography>
        <Typography data-testid="seat-map-subtitle" sx={{ alignSelf: 'flex-start' }}>
          Show Date: {formatShowDate(screening.date, screening.time)}
        </Typography>
        <Typography data-testid="seat-limit-info" align="center">
          You can reserve up to 10 seats per reservation
        </Typography>

        <ScreenIndicator />
        <AuditoriumMap
          occupiedSeats={occupiedSeats}
          selectedSeats={selectedSeats}
          onToggleSeat={handleToggleSeat}
          onToggleCouch={handleToggleCouch}
        />

        <Legend />

        <SelectedSeatsPanel seatIds={booking.seats} />

        <Stack direction="row" spacing={2}>
          <Button data-testid="cancel-button" variant="outlined" onClick={handleCancel}>
            Cancel
          </Button>
          <Button
            data-testid="continue-button"
            variant="contained"
            disabled={booking.seats.length === 0}
            onClick={handleContinue}
          >
            Continue
          </Button>
        </Stack>
      </Stack>
    </Box>
  );
}

